  padding: 96px 0 48px;
  background: #fff;
  scroll-margin-top: 24px;
}

.service-cards .row {
  display: flex;
  flex-wrap: wrap;
  align-items: stretch;
}

.service-cards .service-block {
  display: flex;
  margin-bottom: 24px;
}

.service-cards .service-block:nth-child(2),
.service-cards .service-block:last-child {
  padding-top: 0;
}

.service-card {
  display: flex;
  width: 100%;
  height: 100%;
  flex-direction: column;
  padding: 36px 32px;
  border-radius: 22px;
  background: #fff;
  box-shadow: 0 8px 28px rgba(0, 15, 43, 0.1);
  position: relative;
  text-align: center;
  transition: transform 600ms cubic-bezier(0.22, 0.61, 0.36, 1), box-shadow 600ms ease;
}

.service-card-reveal {
  animation: none;
  transition: opacity 1000ms ease, transform 1000ms cubic-bezier(0.22, 0.61, 0.36, 1), box-shadow 600ms ease;
}

.service-card-reveal.is-restarting {
  transition: none;
}

.service-card-reveal.is-pending {
  opacity: 0;
  transform: translateY(26px) scale(0.975);
}

.service-card-reveal.is-visible {
  opacity: 1;
  transform: translateY(0) scale(1);
  transition-delay: var(--wowoni-service-reveal-delay, 0ms), var(--wowoni-service-reveal-delay, 0ms), 0ms;
}

.service-card::after {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  width: 40px;
  height: 2px;
  margin: 0 auto;
  background: #427ffe;
  content: "";
  pointer-events: none;
  transform: scaleX(0);
  transform-origin: center;
  transition: transform 300ms ease;
}

.service-card-link {
  display: flex;
  width: 100%;
  height: 100%;
  flex-direction: column;
  align-items: center;
  color: inherit;
  text-decoration: none;
}

.service-icon {
  display: block;
  width: 100px;
  height: 100px;
  margin: 0 auto 28px;
  object-fit: contain;
  transition: transform 500ms cubic-bezier(0.22, 0.61, 0.36, 1), filter 500ms ease;
}

.service-card h3 {
  margin: 0 0 16px;
  color: var(--wowoni-navy);
  font-size: 23px;
  font-weight: 700;
  line-height: 1.25;
  text-align: center;
  transition: color 220ms ease, transform 220ms ease;
}

.service-card p {
  max-width: 370px;
  margin: 0 auto;
  color: #1e1e1e;
  font-size: 16px;
  line-height: 25.6px;
  text-align: center;
}

.service-cards .service-card-link:hover .service-icon,
.service-cards .service-card:focus-within .service-icon {
  filter: drop-shadow(0 4px 7px rgba(0, 0, 255, 0.16));
  transform: translateY(-4px) scale(1.14);
}

.service-cards .service-card:hover,
.service-cards .service-card:focus-within {
  transform: translateY(-10px) scale(1.02) !important;
  box-shadow: 0 22px 44px rgba(0, 15, 43, 0.18);
  transition-timing-function: cubic-bezier(0.16, 1, 0.3, 1);
}

.service-cards .service-card:hover::after,
.service-cards .service-card:focus-within::after {
  transform: translateY(-3px) scaleX(1);
}

.service-cards .service-card-link:hover h3,
.service-cards .service-card:focus-within h3 {
  color: #427ffe;
  transform: translateY(-3px);
}

.service-cards .service-icon {
  transition: transform 600ms cubic-bezier(0.16, 1, 0.3, 1), filter 600ms ease;
}

.service-cards .service-card h3 {
  transition: color 300ms ease, transform 400ms cubic-bezier(0.16, 1, 0.3, 1);
}

.service-card-link:focus-visible {
  outline: 2px solid var(--wowoni-blue);
  outline-offset: 6px;
}

.services-action {
