  transition: transform 0.35s cubic-bezier(0.16, 1, 0.3, 1),
    box-shadow 0.35s cubic-bezier(0.16, 1, 0.3, 1),
    border-color 0.3s ease;
  display: flex;
  flex-direction: column;
  position: relative;
  overflow: hidden;
}

/* Sliding gradient top line animation */
.contact-highlight-card::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 3px;
  background: linear-gradient(90deg, #0D7DFC, #376cfd);
  transform: scaleX(0);
  transform-origin: left center;
  transition: transform 0.4s cubic-bezier(0.16, 1, 0.3, 1);
}

/* Soft glowing corner ambient radial gradient */
.contact-highlight-card::after {
  content: "";
  position: absolute;
  top: -30px;
  right: -30px;
  width: 130px;
  height: 130px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(13, 125, 252, 0.12) 0%, rgba(13, 125, 252, 0) 70%);
  opacity: 0;
  transition: opacity 0.4s ease, transform 0.4s ease;
  pointer-events: none;
}

.contact-highlight-card:hover {
  transform: translateY(-8px);
  border-color: #376cfd;
  box-shadow: 0 20px 42px rgba(13, 125, 252, 0.12), 0 4px 12px rgba(0, 15, 43, 0.04);
}

.contact-highlight-card:hover::before {
  transform: scaleX(1);
}

.contact-highlight-card:hover::after {
  opacity: 1;
  transform: scale(1.25);
}

.contact-highlight-header {
  display: flex;
  align-items: center;
