  margin: 0 auto 55px;
}

.contact-offices-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  color: var(--contact-blue);
  margin-bottom: 12px;
}

.contact-offices-title {
  font-size: 38px;
  font-weight: 800;
  color: var(--contact-navy);
  line-height: 1.25;
  margin: 0 0 14px;
}

.contact-offices-desc {
  font-size: 16px;
  line-height: 1.65;
  color: var(--contact-text-muted);
  margin: 0;
}

.contact-offices-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 26px;
}

/* Office Card Design */
.contact-office-card {
  background: var(--contact-white);
  border: 1px solid var(--contact-border);
  border-radius: var(--contact-radius-md);
  padding: 34px 30px;
  box-shadow: var(--contact-shadow-sm);
  display: flex;
  flex-direction: column;
  transition: transform 0.4s cubic-bezier(0.25, 0.1, 0.25, 1),
    box-shadow 0.4s ease,
    border-color 0.4s ease;
  position: relative;
  overflow: hidden;
}

.contact-office-card::after {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 4px;
  background: linear-gradient(90deg, #0D7DFC, #376cfd);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 0.4s cubic-bezier(0.25, 0.1, 0.25, 1);
  border-top-left-radius: inherit;
  border-top-right-radius: inherit;
}

.contact-office-card:hover {
  transform: translateY(-8px);
  border-color: var(--contact-blue);
  box-shadow: 0 20px 45px rgba(0, 15, 43, 0.1);
}

.contact-office-card:hover::after {
  transform: scaleX(1);
}

/* Featured HQ Card */
.contact-office-card.is-headquarters {
  grid-column: span 3;
  background: linear-gradient(135deg, #ffffff 0%, #f4f8fe 100%);
  border: 2px solid rgba(13, 125, 252, 0.28);
}

.contact-office-card.is-headquarters:hover {
  transform: translateY(-8px);
  border-color: var(--contact-blue);
  box-shadow: 0 22px 50px rgba(6, 43, 84, 0.18);
}

.contact-office-card.is-headquarters .contact-office-inner {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 32px;
}

.office-top-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
}

.office-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 12px;
  border-radius: 20px;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.8px;
  background: var(--contact-blue-soft);
  color: var(--contact-blue);
  transition: all 0.3s cubic-bezier(0.25, 0.1, 0.25, 1);
}

.contact-office-card:hover .office-badge {
  transform: translateY(-2px);
