}

.office-name {
  font-size: 20px;
  font-weight: 700;
  color: var(--contact-navy);
  margin: 0 0 10px;
  transition: color 0.3s ease;
}

.contact-office-card:hover .office-name {
  color: var(--contact-blue);
}

.office-entity {
  font-size: 13px;
  font-weight: 600;
  color: var(--contact-blue);
